package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.Map;

/**
 * Validated grace days for grades, in whole days, by grade; a grade's value null: blank, none. A grade left out is left
 * as it is. {@code from} is the from-date typed for each grade (a grade left out: none typed, the sheet's today).
 */
public record GradeGrace(Map<String, Integer> values, Map<String, LocalDate> from) {

    /** The from-date typed for the grade (null: none, the sheet's today). */
    public LocalDate fromOf(String grade) {
        return from.get(grade);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class SaveGradeGrace {
    public void save(@Val GradeGrace grace, @Val Sheet sheet, SettingRepository repository) {
        grace.values().forEach((grade, value) -> repository.saveDated(sheet.id(), DatedSettings.gradeGrace(grade),
                DatedSettings.fromOr(grace.fromOf(grade), sheet.today()), value == null ? null : String.valueOf(value)));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records each grade's grace days just saved, by grade (blank: none), even when they are the ones the grade had. */
public class AuditGradeGrace {
    public void audit(@Val GradeGrace grace, @Val Sheet sheet, @RequestParam("user") String user, Audit audit) {
        grace.values().forEach((grade, value) -> audit.record("SETTING_CHANGED sheet=" + sheet.id() + " by=" + user
                + " key=" + DatedSettings.gradeGrace(grade) + " value=" + (value == null ? "" : value.toString())
                + DatedSettings.auditFrom(grace.fromOf(grade))));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class SaveProofThreshold {
    public void save(@Val ProofThreshold threshold, @Val Sheet sheet, SettingRepository repository) {
        if (threshold.given()) {
            repository.saveDated(sheet.id(), DatedSettings.PROOF_THRESHOLD,
                    DatedSettings.fromOr(threshold.from(), sheet.today()),
                    threshold.value() == null ? null : threshold.value().toPlainString());
        }
    }
}
